  const result = overdueInvoices([paid.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 20000);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
