  assert.equal(issued.ok, true);

  const vatResult = vatSummary([issued.value]);
  const totals = invoiceTotals(issued.value);

  const totalVat = vatResult.reduce((sum, entry) => sum + entry.vat, 0);
  assert.equal(totalVat, totals.vat);
});

test('vatSummary does not mutate invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const invoices = [issued.value];
  const original = JSON.parse(JSON.stringify(invoices));

  vatSummary(invoices);
  assert.deepEqual(invoices, original);
});
